const canvas = document.getElementById('canvas1');
const ctx = canvas.getContext('2d');

canvas.width = 736;
canvas.height = 1162;
/*
const widthLimit = canvas.width / 1;
const heightLimit = canvas.height / 1;
*/
const imagel = new Image();

imagel.addEventListener('load', function(){
/*
    const scale = Math.min(widthLimit / imagel.width, heightLimit / imagel.height);
    const widthEnd = imagel.width * scale;
    const heightEnd = imagel.height * scale;
*/
    ctx.drawImage(imagel, 0, 0, canvas.width, canvas.height);
    const scannedImage = ctx.getImageData(0, 0, canvas.width, canvas.height)
    console.log(scannedImage);//this one shows all colors
    const scannedData = scannedImage.data;
    for(let i = 0; i < scannedData.length; i += 4){
        const total = scannedData[i] + scannedData[i+1] + scannedData[i+2];
        const averageColorValue = total/3;
        scannedData[i] = averageColorValue  + 10;
        scannedData[i+1] = averageColorValue + 30;
        scannedData[i+2] = averageColorValue + 50;
    }
    scannedImage.data = scannedData;
    ctx.putImageData(scannedImage, 0 ,0)
})

imagel.src = 'data:image/jpeg;base64,';

